31:   publish(event: TEvent): SequencedRootEvent<TEvent> {
32:     const sequenced = Object.freeze({
33:       changeSequence: this.changeSequence + 1,
34:       event,
35:     });
36:     this.changeSequence = sequenced.changeSequence;
