53:   async openSnapshotConnection<TSnapshot>(
54:     capture: () => Promise<TSnapshot> | TSnapshot,
55:   ): Promise<RootSnapshotConnection<TSnapshot, TEvent>> {
56:     const baseChangeSequence = this.changeSequence;
57:     const queued: SequencedRootEvent<TEvent>[] = [];
58:     this.barriers.add(queued);
59:     try {
60:       const snapshot = await capture();
61:       let open = true;
62:       const close = (): void => {
63:         if (!open) return;
64:         open = false;
65:         this.barriers.delete(queued);
66:       };
67:       return Object.freeze({
68:         snapshot,
69:         baseChangeSequence,
70:         get queuedEvents() { return Object.freeze([...queued]); },
71:         subscribe: (listener: RootEventListener<TEvent>) => {
72:           if (!open) throw new Error("Root snapshot connection is closed.");
73:           close();
74:           for (const event of queued) listener(event);
75:           return this.subscribe(listener);
76:         },
77:         close,
78:       });
79:     } catch (error) {
80:       this.barriers.delete(queued);
81:       throw error;
82:     }
83:   }
84: 
85:   clear(): void {
86:     this.listeners.clear();
87:     this.barriers.clear();
88:   }
