6: /** Same-live-run projection only. Never sends input or replays a historical queue. */
7: export function handleAgentInputState(payload: AgentInputStateDto, context: AgentContext): boolean {
8:   const previous = context.state.inputProjection;
9:   if (previous?.runInstanceId === payload.run_instance_id && payload.revision <= previous.revision) return false;
10:   context.state.inputProjection = { runInstanceId: payload.run_instance_id, revision: payload.revision };
11:   context.state.recoverableBlock = payload.recoverableBlock;
12:   if (payload.recoverableBlock) context.state.currentStatus = payload.recoverableBlock.state === 'recovering'
13:     ? AgentStatus.Running : AgentStatus.Error;
14:   for (const message of context.conversation.messages) if (message.type === 'user') delete message.pendingInput;
15:   for (const entry of payload.entries) {
16:     // Agent/system deliveries have their existing presentation owner; do not invent user bubbles.
17:     if (entry.sender_type !== 'user' || (!entry.message_id && !entry.dedupe_key)) continue;
18:     const message = buildUserMessageFromProjectionPayload({ content: entry.content,
19:       message_id: entry.message_id, dedupe_key: entry.dedupe_key,
20:       context_file_paths: entry.file_attachments.map(file => ({ path: file.uri, type: file.file_type })),
21:     });
22:     const existing = context.conversation.messages.find(item => item.type === 'user' && (
23:       !!entry.message_id && item.messageId === entry.message_id || !!entry.dedupe_key && item.dedupeKey === entry.dedupe_key));
24:     if (existing) message.timestamp = existing.timestamp;
25:     message.pendingInput = { runInstanceId: payload.run_instance_id, state: entry.state };
26:     upsertUserMessageByIdentity({ context, userMessage: message, retainExistingNonExecutableContextFiles: true });
27:   }
28:   return true;
29: }

25: export const applyLiveAgentStatusEvent = (
26:   context: AgentContext,
27:   payload: AgentStatusPayload,
28: ): boolean => {
29:   const block = context.state.inputProjection ? context.state.recoverableBlock : payload.recoverableBlock ?? null;
30:   const nextStatus = block && block.state !== 'recovering' ? AgentStatus.Error : normalizeAgentRuntimeStatus(payload.status);
31:   const changed = context.state.currentStatus !== nextStatus || context.submissionPending;
32:   context.state.recoverableBlock = block;
33:   context.state.currentStatus = nextStatus;
34:   context.submissionPending = false;
35:   return changed;
36: };
