5: export const isNativeCompactionIdentity = (value: AgentCompactionStatus): boolean => {
6:   const operation = value.compactionOperationId;
7:   return typeof operation === 'string' && operation.trim().length > 0
8:     && value.activityId === `compaction:operation:${operation}`
9:     && ![value.provider, value.sourceSurface, value.boundaryKey,
10:       value.providerEventId, value.providerSessionId].some(Boolean);
11: };
12: 
13: export const isNativeCompactionActivity = (activity: RunActivity): activity is CompactionActivity =>
14:   activity.kind === 'compaction' && isNativeCompactionIdentity(activity);
15: 
16: export const stopNativeCompactionActivity = (activity: CompactionActivity, at: Date): CompactionActivity =>
17:   isNativeCompactionIdentity(activity) && isActiveCompactionPhase(activity.phase)
18:     ? { ...activity, phase: 'stopped', message: 'Stopped', updatedAt: at,
19:         centerTimelineTimestamp: activity.centerTimelineTimestamp ?? at }
20:     : activity;
21: 
22: // Projection covers saved facts, not native live status. Only preserve facts already held
23: // by this run's bounded activity window; live events remain free to start a fresh attempt.
24: export const retainTerminalNativeActivities = (
25:   projected: readonly RunActivity[], current: readonly RunActivity[],
26: ): RunActivity[] => {
27:   const combined = new Map(projected.map((activity) => [activity.activityId, activity]));
28:   for (const activity of current) {
29:     if (!isNativeCompactionActivity(activity) || !isCompleteCompactionPhase(activity.phase)) continue;
30:     const incoming = combined.get(activity.activityId);
31:     if (!incoming || (isNativeCompactionActivity(incoming) && !isCompleteCompactionPhase(incoming.phase))) {
32:       combined.set(activity.activityId, activity);
33:     }
34:   }
35:   return [...combined.values()].sort((left, right) => left.timestamp.getTime() - right.timestamp.getTime());
36: };

